quests[61405] = { id = 61405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Divine Desserts", description = "Recipes very important. Must not be lost!\n\nI learn new foods from many mortals, add to my book. Best way is taste some of thing so can know what is good. You teach recipe to me this way and bring me right ingredients so I cook too. Then taste yours, then taste mine. Helps me learn.\n\nI bring desserts to Ember Court.\n\nFair, yes?", progress = "You ready to give ingredients and taste test?", completion = "Ones that seem simple are harder. All ingredients must be perfect.", objectives = "Collect a sample of Banana Beef Pudding, 30 Aethereal Meat, and 20 Phantasmal Haunch. Then taste-test Stewart's concoction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61406] = { id = 61406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Mushroom Surprise!", description = "I had not realized the fame of my fungi had reached so far. I'd be delighted to provide a mushroom feast to the Ember Court!\n\nHmmm... I will need you to collect some rare specimens and will loan you my favorite foraging bag. It will help you find the very best fungi. It's never failed me.\n\nLet's see, I need tiny lacy bells from Bastion and some of those Ardenweald fancy purple frills. From the very tops of our mushrooms here I will need the feather caps. You'll need to grapple your way up there.", progress = "Have you filled the foraging bag?", completion = "Well, those smell good and ripe! You're pretty good at this, {name}.", objectives = "Collect 18 Feather Caps, 24 Lacy Bell Morels, and 4 Violet Frills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61407] = { id = 61407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Atoning Rituals", description = "If Prince Renathal wishes to impart knowledge of Revendreth's highest calling to his guests, we would be honored to demonstrate the rituals of atonement.\n\nHowever, I must ask for your assistance preparing the necessary components quickly.\n\nCapture nearby fugitive souls that hide from the Lord Chamberlain's corrupt venthyr. Bring them to our avowed ritualists across the halls. They will prepare the souls for our purpose.\n\nSinstone fragments will also help us identify the sins of these lost souls.", progress = "Fugitive souls can be found hiding in the darkest corners of the Halls of Atonement.", completion = "Thank you, {name}. The Accuser and I will personally lead the rituals during the Ember Court.\n\nWe will remind everyone of Revendreth's true purpose.", objectives = "Collect 125 Sinstone Fragments and deliver 2 Fugitive Souls to Avowed Ritualists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61408] = { id = 61408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Glimpse of the Wilds", description = "It would be wonderful to show Revendreth the wild creatures of Ardenweald!\n\nYou can get some Radiant Groupers near the waterfalls. They're fast so you have to grab them as they swim by. \n\nHere's a net to use to subdue the Territorial Waders. They should follow you once you've caught them.\n\nHighland Runestags will let you ride them if you aren't aggressive. Bring a few here to me, please. Watch out for the bulls, they're not at all friendly.\n\nWe will get others to help too. This sounds like fun.", progress = "We need Radiant Groupers, Highland Runestags, and Territorial Waders please.", completion = "Thank you {name}.", objectives = "Bring 3 Highland Runestags, 8 Radiant Groupers and 4 subdued Territorial Waders to Niya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61411] = { id = 61411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Heart Will Go On" }
quests[61412] = { id = 61412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Early End", description = "Within the Hall of Chains lie more constructs that are nearly complete. As we speak, the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages.\n\nIf they are allowed to finish their work, then the destruction we have wrought thus far will make little difference in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost.\n\nThat must not come to pass. Destroy any of these abominations you encounter.", completion = "Every abomination denied is one less foe to contend with when we face Gharmal.", objectives = "Destroy 6 Inert Butchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61414] = { id = 61414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faulty Fireworks (+Safe)", progress = "<Prince Renathal looks at the Flimsy Firework you're carrying with great concern.>\n\nThis cheap party favor could send all of Sinfall up in flames!", completion = "I truly appreciate you bringing these fireworks to me, {name}.\n\nSuch cheap favors have no place at our party." }
quests[61421] = { id = 61421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Blisswing", objectives = "You have rescued both Enothia and myself. Allow me to repay your kindness and join you on your quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61422] = { id = 61422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Duskleaf", objectives = "Finally revenge is served. Or is that justice? Something has been served for me, and maybe now I can serve you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61423] = { id = 61423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Karynmwylyann", objectives = "My memories have been restored and now I need a new path. I shall join you along yours for a time if you wish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61424] = { id = 61424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Chalkyth", objectives = "Allow me and my saber to thrash your enemies once more!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61425] = { id = 61425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lloth'wellyn", objectives = "Thank you for the help, I made a note of it. I believe I may also be able to help you further as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61426] = { id = 61426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Yira'lya", objectives = "Please take me back to Ardenweald. I can do nothing to help from here.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61427] = { id = 61427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blisswing's Rescue" }
