quests[61432] = { id = 61432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Journals", progress = "What is that you have found?", completion = "I recognize that handwriting, are these actually the prince's pages? I will make sure they make their way to Sinfall, the court is grateful you returned them." }
quests[61433] = { id = 61433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giant Lungcap", progress = "Is that... a lungcap?\n\nHow did you possibly find one of those here in Revendreth?\n\nNo matter. Throw it on a platter!\n\nPerhaps they will not notice how terrible it tastes.", completion = "What it lacks in flavor, it more than compensates for in size.\n\nI should be able to fill three platters with this if carve it correctly." }
