quests[61436] = { id = 61436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Trip", description = "Now that you have the catalyst, you need only bring it to Mortimer in Maldraxxus. Our last correspondence indicates that his laboratory is still in-tact within the former House of Plagues.\n\nExercise caution in your journey--what remains of the house is fraught with danger, and Mortimer himself has earned a less than pristine reputation among his peers.", completion = "Ah, yes! You must be the one from Bastion! Marvelous!", objectives = "Bring the Catalyst of Creation to Mad Mortimer in the House of Plagues in Maldraxxus.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
