quests[61448] = { id = 61448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blob of Slime (+Clean)", progress = "<Prince Renathal leans back and turns away while extending an arm forward.>\n\nThis filth must be disposed of immediately!", completion = "Thank you for ensuring our party is as pristine as it should be." }
quests[61449] = { id = 61449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leatherworking: Steelhide Leather Harness" }
quests[61450] = { id = 61450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster of Seeds (+Humble)", progress = "What do we have here? An assortment of seeds?", completion = "While not known for their flavor, I'm sure these morsels will please one of the picky palates in attendance." }
quests[61467] = { id = 61467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mining: Luminous Solenium Cluster" }
quests[61468] = { id = 61468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skinning: Plush Copperfur Pelts" }
quests[61469] = { id = 61469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailoring: Woven Gossamer Tunic" }
quests[61473] = { id = 61473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sourcing Your Own Materials", description = "I can aid you in crafting many pieces of equipment for your soulbinds.\n\nThough they may only equip one at a time, each piece grants a new ability that they may not have without it.\n\nThis time you must source your own materials from around the Shadowlands. When you have collected them, return to me and we can create the footpads!", progress = "You find materials okay? Blueprint can help!", completion = "Boots? Very nice! I hold on for safe keeping.", objectives = "Craft the Herald's Footpads with Dactylis. Check the materials in the crafting window to learn where you can gather them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61475] = { id = 61475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Forest", description = "I knew we were gonna get along! Welcome to our covenant. Well, almost.\n\nThere's just a few details left. Little things. You know. Oaths to be made, blood pacts to sort out, firstborns to be promised.\n\n<Moonberry snorts a laugh.>\n\nI'm just kidding!\n\nWell, not about the oaths part. We take those seriously around here.\n\nI'll meet you at the camp outside the Heart of the Forest!", completion = "This is going to be such fun!", objectives = "Meet Lady Moonberry at the Refugee Camp beside the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61477] = { id = 61477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling the Champions" }
quests[61478] = { id = 61478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humble Beginnings", description = "With Humility's Guard whole once more, you may be able to coax Athanos back into the arena.\n\nTravel to Aspirant's Crucible, where your journey began so long ago. Seek Forgelite Sophone--she guides all those who seek an encounter with Athanos.\n\nPresent the spear to her. She will know your intent and instruct you further.", progress = "What is that you have there?", completion = "I never thought I would see this spear again! This will be most interesting.", objectives = "Bring Humility's Guard to Forgelite Sophone in Aspirant's Crucible.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61479] = { id = 61479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of Shapes", description = "<Moonberry looks serious.>\n\nMortal though you are, you have chosen to become one of our champions. While you uphold our cause, we are obligated to extend hospitality to you within our sacred hall and grant you certain boons.\n\nAs a member of the Court of Night, I can bestow our powers on chosen mortals.\n\n{name}, {class} of Azeroth,  I bid you welcome to the first tree, Tirna Achiad, the Heart of the Forest.\n\nPlease, follow me.", progress = "Accept this boon and use it for the benefit of Ardenweald.", completion = "May this boon aid you in the trials ahead, {name}.\n\nBefore our Queen grants you our power and we accept you formally into our midst, there are certain... traditions which we must uphold.", objectives = "Accompany Lady Moonberry into the Heart of the Forest and take part in the ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61485] = { id = 61485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Only Say This Once", description = "At last, we are fully prepared to enact the baroness's plan.\n\nNow that you have arrived, I will recount our roles one final time. Then we will seize our fate.\n\nListen closely.", completion = "Let us put our plan into motion.", objectives = "Speak with Whisperer Vyn about the plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61486] = { id = 61486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Banshee's Champion", description = "I... we... I mean... he's...\n\n<The young courier gulps.>\n\nWe found him. We found the Blightcaller.\n\nI was on patrol like I'd done a hundred times before only there he was sitting on the front porch of that old house with those terrible dogs and I swear he smirked at me and stared with those fiery red eyes and--\n\n<The young courier wipes his brow.>\n\nHe's at the Marris Stead. Our forces have him surrounded, but, uh...\n\nYou should probably gather your friends. I don't think he plans to surrender.", progress = "What news do you bring of the Blightcaller?", completion = "At long last, one of the most notorious enemies of the Alliance has met his end.\n\nWell done, {name}. Well done indeed.", objectives = "Confront Nathanos Blightcaller at Marris Stead in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61488] = { id = 61488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Banshee's Champion", description = "<The messenger appears visibly shaken.>\n\nWord has reached us of... well, I'm not quite sure how to put it...\n\nThe Blightcaller has been found.\n\nHorde forces have been scouring Azeroth for any sign of him. Determined to make him answer for his crimes.\n\nOne of our Argent patrols has found him. Not hiding in some distant land. Just... waiting at his old homestead.\n\nWe have him surrounded, but, uh, I confess I don't like our odds.\n\nPerhaps you could gather your allies and bring him to justice.", completion = "<A wry smile crosses the Regent Lord's face.>\n\nA fitting end to the Blightcaller. I only wish I had been there to see it.", objectives = "Confront Nathanos Blightcaller at Marris Stead in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61489] = { id = 61489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Hearsay and Heresy", description = "Echthra has taken residence in one of the few remaining structures in the former House of Eyes in Maldraxxus.\n\nBring the anointment oil to her, and she should allow you to capture her memory. Take caution, for she is well-known both as a master marksman and--perhaps more notably--for her quick trigger finger.\n\nGood luck, Maw Walker.", progress = "Be cautious. There are many in the House of Eyes who would not tolerate your presence.", completion = "Let us have words quickly--before I change my mind.", objectives = "Find Echthra in the House of Eyes in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61490] = { id = 61490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War of Information", description = "Ah, the anointment oil. I had expected one of Adrestes' recruits.\n\nNo matter. You seek my memory for your trials, yes? I am afraid mere oil will not suffice.\n\nWith our house gone, we are left to fend for ourselves. Though this tower offers some protection, we are left cornered to any who may desire our end.\n\nInformation is the key to survival. Use my anointed talisman to give me eyes across all the realms...even in Bastion. Follow the list precisely--no questions.\n\nThen can we resolve payment.", progress = "There will be no negotiation in this matter.", completion = "Already my vision grows. The pact is sealed.", objectives = "Place Eyes of Hatred in the House of Rituals in Maldraxxus, Eonian Archives in Bastion, Tirna Vaal in Ardenweald, and Castle Nathria in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61492] = { id = 61492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princeguard", description = "Renathal carries himself well, but hides great pain. His wounds from Denathrius have not healed.\n\nHe is vulnerable.\n\nHe intends to send you to secure his old fortress of Darkwall Tower with banners and rely on his own strength to deter enemies. This is a poor tactical choice.\n\nTake this small reserve of anima with you and revive Chelra the Bladewall. She was last seen at Darkwall. Revive her and she can aid you in taking the tower.", progress = "I have suffered in stillness for months. I worried I would never wake again.", completion = "Well fought. That will not hold them for long, but it should buy Renathal the time he needs.\n\nThank you, mortal, for the infusion. I shall put this precious anima to good use while it lasts.", objectives = "Revive Chelra the Bladewall and drive enemies out of Darkwall Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61509] = { id = 61509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shinies of Bastion", description = "Chordy is bored, boooored!\n\nYou want to go look for luckydos? Go on adventure with Chordy?\n\nWe go to land of wing people, go look for valuable luckydos there.\n\nReady?", progress = "Did we find anything good?", completion = "Interesting, these are in better condition than most of Chordy's finds.\n\nThese will serve us well. Thank you, Maw Walker.", objectives = "Use Chordy to locate and collect 10 valuable salvage around Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61510] = { id = 61510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bountiful Haul", description = "Chordy want to go on adventure! You want to go too, yes?\n\nI scavenge, weapons, armor, and valuable luckydos! Though, luckydos seem to be in short supply these days.\n\nWe go to land of tree people! If we search together, we'll find many luckydos!", progress = "Did we find anything good?", completion = "Where did you find these? They're positively covered in filth!\n\nUgh, that smell! Here, take this and go clean yourself up.", objectives = "Use Chordy to locate and collect 10 valuable salvage in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61511] = { id = 61511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Things They Leave Behind", description = "Chordy bored. Chordy want to go on adventure! You want to go too, yes?\n\nPale people in tall buildings have many shinies and luckydos. We go there and find some for ourselves!\n\nYou ready to go?", progress = "Did we find anything good?", completion = "Interesting finds. These will be quite useful.\n\nThank you, Maw Walker.", objectives = "Use Chordy to locate and collect 10 valuable salvage in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61517] = { id = 61517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zz" }
quests[61518] = { id = 61518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow Me", progress = "Keep your eyes open.", completion = "It seems we've been discovered. Times like these demand flexibility.", objectives = "Follow Navigator Xennir to the rendezvous point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61520] = { id = 61520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy of My Mnemis" }
quests[61522] = { id = 61522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", progress = "Yes? Did you find anything on your supply run?", completion = "<Rathan gives Flytrap an apprehensive look.>\n\nThat's... that's great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>", objectives = "Return the Bone Carcass to Rathan at Butcher Block.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61523] = { id = 61523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", progress = "Yes? Did you find anything on your supply run?", completion = "<Rathan gives Flytrap an apprehensive look.>\n\nThat's... that's great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>", objectives = "Return the Bone Carcass to Rathan at Butcher Block.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61524] = { id = 61524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ember Court", description = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker.\n\nBe sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court.\n\nRemember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy!\n\nTalk to Lady Ilinca if you have any questions about guests.\n\nOnce everything's ready, talk to me and I'll open the court!", completion = "Now THAT was a court to remember!\n\nHow are you going to top that next week?", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61525] = { id = 61525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ember Court", description = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker.\n\nBe sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court.\n\nRemember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy!\n\nTalk to Lady Ilinca if you have any questions about guests.\n\nOnce everything's ready, talk to me and I'll open the court!", progress = "I can't wait to see who attends today's court!", completion = "Now THAT was a court to remember!\n\nHow are you going to top that next week?", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61526] = { id = 61526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ember Court", description = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker.\n\nBe sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court.\n\nRemember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy!\n\nTalk to Lady Ilinca if you have any questions about guests.\n\nOnce everything's ready, talk to me and I'll open the court!", progress = "I can't wait to see who attends today's court!", completion = "Now THAT was a court to remember!\n\nHow are you going to top that next week?", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
