quests[61539] = { id = 61539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liches Get Stitches" }
quests[61540] = { id = 61540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Winging It" }
quests[61541] = { id = 61541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forge of Bonds", description = "{name}, are you ready for another gift?\n\nThe next boon we grant thee is one of bonds. As you have bound yourself to us, we shall bind to you. In the binding of souls, we become something greater.\n\n<Moonberry leans in close.>\n\nSounds scary, huh? Don't worry! You and your soulbind will both strengthen each other.\n\nWhen I asked for volunteers, many fae stepped forward. I picked someone I just know you're going to like. And this will be a boon for her, too.\n\nGo to Flutterby. She'll help you both.", completion = "Oh, wow! I love guiding soulbinding! It's my favorite duty!", objectives = "Meet Flutterby at the Forge of Bonds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61542] = { id = 61542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of Binding", description = "<Flutterby clasps her hands before her and assumes an air of tranquility.>\n\nSoulbinding is not an irrevocable act. However, such a bond must be carefully considered before it is made.\n\nYou and your soulbind will know each other's hearts and minds. Your hopes and fears; your dreams and memories; all will be shared between you. \n\nAs long as the bond exists, you are intertwined; always together even when apart.\n\nOnce complete, your connection will transcend physical space and empower you both.", progress = "When you are ready, we may proceed.", completion = "You... have lived a very interesting life.", objectives = "Complete the soulbinding ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61543] = { id = 61543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herbalism: Lambent Vigil's Torch" }
quests[61544] = { id = 61544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herbalism: Lush Widowbloom" }
quests[61545] = { id = 61545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herbalism: Engorged Marrowroot" }
quests[61548] = { id = 61548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Me Free", description = "Ansid has been captured and imprisoned by the foundry's guards.\n\nIt seems they were expecting us, completely shattering the element of surprise. My baroness would be disappointed in my lack of foresight.\n\nThis plan cannot succeed without Ansid. One of these soldiers is bound to possess the key to his cage.\n\nShould you find it, we may yet carry out my baroness's will.", progress = "Take caution.", completion = "Expertly navigated. Perhaps you should pilot the necropolis.", objectives = "Find the Ossein Key on one of the Ossein Strongarms and use it to free Ansid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61549] = { id = 61549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drought Conditions" }
quests[61550] = { id = 61550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strengthening the Bond", description = "I know how you feel... and what you have endured for the sake of your world. \n\nYou now know of my own triumphs and tragedies as well.\n\nOur bond will grow stronger over time. But for now, let us see what it has granted us.\n\nArdenweald has needs of us. We must do everything in our power to save it.", progress = "We are stronger together.", completion = "Together, we can do anything.", objectives = "Activate a Soulbind Power using the Forge of Bonds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61551] = { id = 61551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush 'Em All", description = "The mooring platform will be our best launching point to access the necropolis above. But one more fight remains before us.\n\nEnforcer Borgulla oversees all of the work efforts that take place here. We'll need to eliminate her if we are to proceed unhindered.\n\nShe is a formidable foe. It appears Ansid has kept some of his explosives on his person. Let us utilize this advantage.", completion = "Your strength never fails to impress me.", objectives = "Use Ansid's Explosive to kill Enforcer Borgulla.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61552] = { id = 61552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt Watches", description = "The Wild Hunt protects. Many eyes watch for danger. Many ears listen for secrets.\n\nWatcher Vesperbloom directs the eyes and ears of the forest.\n\nSeek out our new growth, then turn to her for guidance.", progress = "Ah. You're here. Good.", completion = "We have much to do.", objectives = "Activate Adventures then seek out Watcher Vesperbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61553] = { id = 61553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Where to Strike", description = "It is the Wild Hunt's duty to hunt down those who would harm our charges and to ensure the security of our borders. But as the crisis has grown, so have our duties to Queen and Grove.\n\nThis is where I come in. It is my duty to be aware of all that goes on within the endless forest. It is my charge to help deploy our resources, so that we may aid our queen.\n\nAllow me to demonstrate...", progress = "Every victory furthers our cause.", completion = "They will succeed in their mission, I have no doubt.", objectives = "Use the Command Table to send your forces on an adventure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61554] = { id = 61554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Play's The Thing", description = "You may be wondering about the last boon we may grant thee, O' champion of Ardenweald, petitioner to our Hunt.\n\n<Vesperbloom could be smirking... Or it could be a trick of the light.>\n\nBefore our Queen grants you our power and we accept you formally into our midst, there are certain... Traditions which we must uphold.\n\nLady Moonberry awaits you in the Sanctum Hall with more information.\n\nBreak a leg.", sourceObjective = "Seek out Lady Moonberry in the Heart of the Forest central hall.", sourceObjectiveStatus = "unverified-source-field" }
quests[61555] = { id = 61555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Inquisitor Vetar" }
quests[61556] = { id = 61556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Crashers" }
quests[61557] = { id = 61557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Echo in the Darkness", completion = "<Bolvar grimaces in pain.>", objectives = "Meet Bolvar Fordragon in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61558] = { id = 61558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord's Vision", description = "<Thrall's brow is furrowed.>\n\nWe were speaking with the Highlord when he was struck by a jolt of agony.\n\nHe said he could see something stirring in the Maw. Inside the Jailer's tower.\n\nThe pain seems to be getting worse. We need to find out what he's sensing.", progress = "We must know the truth.", completion = "This is dire indeed.", objectives = "Find out what Bolvar senses inside Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61559] = { id = 61559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mourneblade Born", description = "While his father was missing, I cared for Anduin like a son. To see him like that, at the mercy of Sylvanas...\n\n<Bolvar's eyes flare with fire.>\n\nSomething must be done.\n\nTake a moment. Let me know when you are ready to discuss what comes next.", completion = "We have to save Bolvar!", objectives = "Discuss the vision with Bolvar and the others.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61564] = { id = 61564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacksmithing: Polished Kyrian Shield" }
quests[61565] = { id = 61565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[61567] = { id = 61567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Intent", description = "My spies have identified several astral projectors that Margrave Gharmal uses to rally their troops in the Stitchyard.\n\nI do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor.\n\nSee to it that these projectors are destroyed. We believe them to be along the yard's perimeter.", completion = "Gharmal's influence runs deep in this place, but it will fade more quickly thanks to your efforts.", objectives = "Destroy the Southwestern, Northwestern, and Notheastern Astral Projectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61569] = { id = 61569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keys to the Ruin", description = "At last, our target is within reach.\n\nThe necropolis rests above us, moored to this platform by a necrotic restraining bolt.\n\nTwigin can fly you to the apex of the necropolis. It will be ours to command once you insert this keystone.\n\nWe will prepare for our departure. Rejoin us when you are done.\n\nVictory will soon be ours.", progress = "Our mission is nearly complete.", completion = "Come, {name}. Would you not witness your success firsthand?", objectives = "Fly with Twigin to the necropolis's apex and plug in the Runic Keystone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61586] = { id = 61586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machinations of War", description = "With Bastion as our ally, we have the strength to crush Gharmal and the House of Constructs.\n\nWe'll gather the supplies for the attack, but our soldiers need a great champion to follow into battle.\n\nProve to them that you are the champion they seek.", completion = "Well done, Maw Walker. Our forces are prepared to strike.", objectives = "Increase your Renown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61593] = { id = 61593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crisis of Memory" }
quests[61594] = { id = 61594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Way Out", description = "We are fully prepared to launch the necropolis. We must hurry before Margrave Gharmal tries to interfere.\n\nSpeak with Vyn when you are prepared, but we mustn't waste time.\n\nWe will cast our shadow upon all of Maldraxxus.", completion = "It is time to depart.", objectives = "Tell Whisperer Vyn to launch the necropolis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
