quests[61616] = { id = 61616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ember Court", description = "We've got everything we need to host our first real Ember Court whenever you're ready, Maw Walker.\n\nTake a moment to finalize everything, and then we'll open court!\n\nRemember, we're trying to impress Cryptkeeper Kassir and convince him that we know what we're doing, so make sure you choose the refreshments and entertainment we hired for him!\n\nOnce everything's ready, let me know and I'll open the court!", progress = "Cryptkeeper Kassir is going to love this!", completion = "Incredible! Flawless! The perfect party herald!\n\nAnd you did well too.\n\nLet's do this again next week!", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress your guest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
