quests[61631] = { id = 61631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drust Between You and Me" }
quests[61635] = { id = 61635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubled Souls", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", completion = "So many souls, we have much work to do!", objectives = "Take the construct requests from the souls present.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61637] = { id = 61637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unity", description = "A unique construct has chosen to join us, but its unethical creation leaves it most unsettled.\n\nThe fusing of fragmented Kyrian souls within this construct, gives it pain and suffering. We must find a way to harmonize these souls so they can live together in peace.\n\nCreate the Bindings of Wellbeing and bring ease to the Soulfused Construct.", progress = "Have you helped this construct?", completion = "So many souls now in harmony. Perhaps with time this construct will find happiness and a home here.", objectives = "Bring ease to the Soulfused Construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61638] = { id = 61638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Solution", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", completion = "So many souls, we have much work to do!", objectives = "Take the construct requests from the souls present.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61667] = { id = 61667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged in Secret" }
quests[61689] = { id = 61689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crisis of Memory" }
quests[61697] = { id = 61697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Age", description = "With the final empowerment in place, our renewed Crest of Ascension stands bolstered by the might of not just Bastion, but all covenants.\n\nSoon new Ascended will grace these halls once more as aspirants finish their long-awaited trials.\n\nNone of this would be possible without your aid, Maw Walker. The honor of activating the Crest at last is yours.", progress = "This is a glorious moment for all kyrian.", completion = "With the Crest complete at last, we must next turn our eyes back to the Forsworn.\n\n<You notice Grubby looking at you expectantly.>", objectives = "Activate the Crest of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61699] = { id = 61699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Much to Goo On" }
quests[61701] = { id = 61701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching the Grove", description = "It is clear that a struggle took place here. I fear that Kivarr may have been taken by the Drust.\n\nI scouted the surrounding area before you arrived. Eventide Grove has been overrun.\n\nThe Drust cannot have taken her far. We may yet be able to find her. I just pray that we are not too late...", completion = "Ulfar sent you to find me? Free me from this cage, and I will do what I can to aid you.", objectives = "Search for Kivarr at Eventide Grove in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61702] = { id = 61702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swift Intervention", description = "The Drust just took Kivarr away. They said they were going to sacrifice her in one of their rituals!\n\nIf we hurry, you may still be able to save her! I've seen where the Drust keep their sacrificial altar... it's scary, but I can take you there!\n\nThere's no time to waste! Follow me!", completion = "Not a moment too soon! I appreciate your punctuality.\n\nMy den is not far away. We should hurry before more Drust arrive.", objectives = "Rescue Kivarr from Eventide Grove in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61703] = { id = 61703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nox Root", description = "In order to perform the ritual, I will need some nox root from Darkreach.\n\nIt is a unique plant that only grows within soil that has been corrupted by Drust magic.\n\nDarkreach lies to the west, not far from my den. What was once a peaceful, verdant grove is now filled with blight and ruin.\n\nI will travel to the Heart of the Forest to prepare the ritual. Meet me there when you have gathered the nox root.", progress = "Have you brought the reagents?", completion = "Good, you were able to find enough nox root for the ritual. Unfortunately, we have another problem...", objectives = "Collect 12 Nox Root from Darkreach in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61704] = { id = 61704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Guest RSVPs", description = "Prince Renathal will wish to invite certain guests to each Ember Court.\n\nIn the future, we'll be able to adjust the guest list to make it easier to please everyone in attendance. But, we should follow the Prince's lead on this first one.\n\nWork with Lord Garridan and Lady Ilinca to ensure that Cryptkeeper Kassir is able to attend and returns his RSVP.\n\nIf you haven't met Cryptkeeper Kassir yet in your adventures, you may need to introduce yourself before he'll listen to you.", completion = "The prince is wise to hold court. A timeless tradition of influence and prestige in this realm.", objectives = "Speak with Lord Garridan to see your Guest List, then meet Cryptkeeper Kassir to earn his RSVP.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61705] = { id = 61705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Refreshments", description = "We should always serve refreshments in the Ember Court, tailoring our choice of refreshment type to the preferences of our guests.\n\nLuckily, I know our first guest well. Like Theotar, he prefers it to be Formal.\n\nWork with Picky Stefan to acquire everything we need to throw a fancy tea party.", completion = "You smart! Tubbins tea is best tea!", objectives = "Speak with Picky Stefan to see your Refreshment options, then complete Tubbins's quest to earn the tea party contract.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61706] = { id = 61706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Entertainment", description = "Everyone loves entertainment!\n\nOur first guest is from the Halls of Atonement, so he will certainly appreciate a presentation of the powerful rituals the Accuser is capable of.\n\nWork with Hips to acquire everything we need to host atoning rituals at the Ember Court.", completion = "A new court in Revendreth? The Accuser must be pleased that you chose to include rituals of atonement in the festivities.", objectives = "Speak with Hips to see your Entertainment options, then complete Gresit's quest to earn the rituals contract.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61707] = { id = 61707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crumbled Reality", description = "As the drought and devourers eat our buildin's, the structures lose their hold on reality. Thing is, it ain't a clean process. Some of that debris is still infused with anima.\n\nWhen your out, be a stoneback an' bring us whatever infused debris you can find.\n\nSee, we can recycle it into new structures as you hero types go and get the anima flowin' again.\n\nBring it here an we'll get it sorted.", progress = "Impressed 'ow much you can carry with 'em 'itty bitty arms.", completion = "Everythin's bricks n' mortar with you. Love it.", objectives = "Recover 100 Infused Rubble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61708] = { id = 61708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drawing Out the Poison" }
quests[61709] = { id = 61709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witch's Satchel", description = "I sent Ara'lon to steal a witch's satchel from the Drust... a dangerous task from which he has yet to return.\n\nThe Drust's nightscreamers carry many reagents we need to perform the ritual. We cannot proceed without one.\n\nYou must go to the Oaken Assembly to procure one of their satchels... and find Ara'lon, if you can.", progress = "Do you have the satchel? And what of Ara'lon?", completion = "This contains everything we need. Give me a moment and I will prepare the reagents for our ritual.", objectives = "Collect 1 Witch's Satchel from the Oaken Assembly in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61710] = { id = 61710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Spear", description = "<The shattered remains of a sylvari spear litter the ground. You recognize the spear as belonging to Ara'lon.\n\nThis confirms that Ara'lon was here. Unfortunately, he is nowhere to be found.\n\nLord Herne will want to know of your discovery.>", progress = "What news do you bring?", completion = "Though this bodes ill, I am not ready to give up hope that Ara'lon survived. He may still be out there.\n\nI will assemble a search party. We will find him and bring him home... no matter what fate has befallen him. Thank you.", objectives = "Deliver the remains of Ara'lon's spear to Lord Herne at Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61711] = { id = 61711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Purification", description = "I have finished making preparations for the ritual. The moment of truth has come.\n\nThe Drust fetish that Ulfar gave you will channel the ritual's power into Gweyir. It should counteract the curse that imprisons her mind.\n \nThis will not be pleasant. It may not even work. But this is the only chance we have to free her.", progress = "The ritual is our only hope of freeing Gweyir. We must try...", completion = "You performed the ritual admirably, but the Gorak Zhar's power was too strong for Gweyir to withstand. There is nothing more we can do, I am afraid.\n\nIt seems the masked fae are lost to us after all...", objectives = "Complete the Ritual of Purification.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61713] = { id = 61713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Charm of Quickness", description = "<You have discovered plans for a charm that seems to make your soulbinds fleet of foot in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Charm of Quickness to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61714] = { id = 61714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gilded Abacus", description = "<A beautifully crafted abacus rests in your hands. Its frame glimmers and shines in the light, its beads smooth auric orbs.\n\nYour steward will appreciate this as not only a useful gift, but an exquisite one.>", completion = "<Your companion stares in awe.>\n\nNo words to say... so beautiful! Can keep track of much more now. But what to count...\n\nAha! Count your things! No worry, am excellent counter. Woo-woo!", objectives = "Summon your steward companion via Summon steward, then give them the Gilded Abacus.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61715] = { id = 61715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Request of the Highlord", description = "The information you uncovered in Maldraxxus should quell the drums of war between the Necrolords and the Kyrian.\n\nAnd this message from the Primus... extraordinary!\n\nI would advise you to enlist Highlord Fordragon's counsel, but he appears preoccupied. Visitors from your world have come to seek him out. Quite insistently, I might add.\n\nThe nuances of mortal interaction elude me. But it seems the nature of their dialogue was rather... intense.\n\nPerhaps you can assist the Highlord with this matter.", completion = "<Even through his scarred, molten visage, the emotion on Bolvar's face is plain.>\n\nMy daughter... here. I never thought...", objectives = "Speak to Bolvar Fordragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61716] = { id = 61716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Glimpse into Darkness", description = "When I put the Lich King's crown upon my head, I wanted the world to believe I was dead. Even my daughter, Taelia. I... thought a lie would be kinder than the truth.\n\nBut she is no longer the little girl I left in Kul Tiras. I see my choice was a selfish one.\n\n<Bolvar pauses.>\n\nShe and Lady Menethil have asked me to peer into the Maw to see if our allies yet live. It is a dangerous request, but one I cannot refuse.\n\nHelp me focus on the broken helm. Together, we may find a glimpse of truth.", progress = "There is much to do.", completion = "A troubling vision indeed. But we must not give up hope.", objectives = "Witness Bolvar's vision of the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61717] = { id = 61717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormling Piper: Tranquil Pools" }
quests[61725] = { id = 61725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Mementos", progress = "I anticipate the timely return of our stolen merchandise, Maw Walker.\n\nTheir pilfering leaves a blemish on what could otherwise be a perfectly satisfying event.", completion = "<Keeper Ta'saran carefully inspects each memento.>\n\nThese are all in adequate condition. Their return shall be noted in the logs.\n\nYou needn't fear a reprisal for their theft any longer." }
quests[61728] = { id = 61728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valis the Cruel" }
quests[61729] = { id = 61729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Rahel", objectives = "Rahel has arrived from Darkhaven to assist us with, and I quote, \"killing anybody.\" She is quite eager to enter the fray.\n\nShe seemed rather upbeat at the prospect of working with you again, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61730] = { id = 61730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive King", description = "King Anduin has not been found inside Torghast. I fear we could spend eternity searching those endless corridors to no avail.\n\nWe must know what fate has befallen him. To peer into the tower represents a grave risk, yet we have little choice.\n\nStand with me, {name}. We will use the broken Helm of Domination to see into that hellish place.\n\nPerhaps together we can hold back the hungry darkness.", progress = "We must peer into Torghast before Anduin is lost to us.", completion = "Anduin may appear unharmed, but his soul is imperiled.\n\nSylvanas Windrunner cannot be allowed to carry out her plan.", objectives = "Use the Helm of Domination to peer into Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61731] = { id = 61731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Curios", progress = "Curious. Most curious trinkets...\n\nMay I keep to study? Will learn much.", completion = "Most intriguing! Thank you!\n\n<Mikanikos immediately begins disassembling one of the trinkets to study.>" }
quests[61733] = { id = 61733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Bag of Creepers", description = "Right. You've been a polished bit of gray so far and it's appreciated from the bottom up for sure.\n\nWell, now I got a task for 'ou that would help all of us dredgers put that anima you obtained to good use.\n\nCreepers.\n\nNot just any creepers, but 'em mire creepers. 'Ey got a look about 'em and a taste about 'em that just sings when you put it to good use.\n\nAs you go trippin' around Revendreth, grab any creepers ya find an' stick 'em in this here sack. I'll pay ya.", progress = "Creepers. 'Ey like chewin' on the mortar at holds all these walls up.", completion = "Well then, look at that!\n\nA big ol' bag of Creepers, with their squinty eyes and mold smellin' breath.\n\nAin't 'ey cute? \n\nHavin' a few a these around the lads while they work will really help morale. Much appreciated from all of us.", objectives = "Collect 20 Mire Creepers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61734] = { id = 61734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Census of Sins", description = "The Curator once knew the contents and locations of every sinstone in Revendreth dating back to the founding of this realm.\n\nSadly, her time in the Maw disrupted those essential parts of her vast intellect and we can no longer rely upon her for such knowledge. At least, not for a while. And so it falls to me to rebuild a 'living' archive.\n\nAs you venture into Revendreth I would ask that you recover the contents and location of certain sinstones. This will help us orient our archive.", completion = "With time and enough information we may be able to anchor the Curator's knowledge so that she once again becomes the invaluable resource that she once was.", objectives = "Inspect 7 Lost Sinstones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61735] = { id = 61735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaken Our Allies", description = "I have need of your services.\n\nI have identified a collection of stoneborn throughout Revendreth whom may be swayed to our cause, or were already members of our cause before returning to their stone slumber.\n\nYou have provided us with the anima we needed, now it is time to put it to use. Seek out our allies and awaken them. I have fashioned an anima container for easier transport to aid in this endeavor. \n\nWe need an army if we are to face an army.", completion = "Terrifying, aren't they? Magnificent weapons crafted by the finest arts perfected since the coalescing of the Shadowlands themselves. \n\nThey shall prove invaluable in the times to come.", objectives = "Awaken 15 Allied Stoneborn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61736] = { id = 61736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Away", description = "There is much you need to be told, {name}.\n\nThe Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked.\n\nWhat's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war.\n\nSpeak to Whitemane. She can tell you the rest.", sourceObjective = "Speak to Sally Whitemane about the abductions.", sourceObjectiveStatus = "unverified-source-field" }
quests[61737] = { id = 61737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Away", description = "There is much you need to be told, {name}.\n\nThe Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked.\n\nWhat's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war.\n\nSpeak to Nazgrim. He can tell you the rest.", sourceObjective = "Speak to Nazgrim about the abductions.", sourceObjectiveStatus = "unverified-source-field" }
quests[61738] = { id = 61738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Lost Chalice Band", description = "Hips was smart to send you my way. The Lost Chalice Band plays the best music this side of the Maw!\n\nThe band is not quite ready to tour yet, however.\n\nThe musicians are all safe in the crypt behind me, but their instruments have been confiscated by our obnoxious neighborhood authorities!\n\nNoise complaints and all that.\n\nHelp me get those back, and perhaps recruit a few groupies and roadies along the way to help out, and we shall throw the best concert your court has ever seen!", progress = "Any venthyr or dredger will do. We are not picky about our fans.", completion = "I do not know what promotional tricks you used, but it worked.\n\nA whole stream of dredgers and venthyr stopped by to join the band crew!\n\nThe Lost Chalice Band is ready to tour!", objectives = "Use band posters to recruit 10 groupies and 10 roadies and recover 3 Confiscated Band Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61739] = { id = 61739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Baron", description = "It has come to my attention that you seek to uncover a plot by the baron Kel'Thuzad. \n\nThat upstart has been a thorn in my side since he arrived at the House of Rituals. Not only did he pilfer my rightfully earned title, he has since shut me out of the house's dealings.\n\nI have yet to find evidence that would mar Sin'dane's adoration for her new baron, and thus I offer an arrangement. I grant you access to the House of Rituals, and in return you help me bring down Kel'Thuzad.\n\nDo we have an accord?", completion = "<Balmedar's voice resonates from the floating eye.>\n\nYou didn't really think I would risk meeting you here in person, did you?\n\nCome, we have much work to do.", objectives = "Open Balmedar's Supplies at the tower near the Scaplian Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61740] = { id = 61740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing Favorites", description = "We will have to construct an illusion to allow you entry into the House of Rituals. However, not just any illusion will do. In order to join Kel'Thuzad's inner circle, we require something... specific.\n\nWe're going to need a body.\n\nFortunately for us, one of the baron's favorite acolytes is performing a ritual outside of the house itself. You'll need to fight your way to her, but of that I'm sure you're capable.", progress = "Don't you have a corpse to procure?", completion = "I must say it was satisfying watching you wipe the smug look off of Nelesis's face. She always thought she was so superior.\n\nBut enough revelry. We have work to do.", objectives = "Defeat Acolyte Nelesis and bring her corpse back to the tower near Scaplian Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61741] = { id = 61741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfered Power", description = "The illusion ritual will require a substantive amount of anima to complete. Since such a resource isn't simply lying around these days, we will need to take some.\n\nThe abominations from the House of Constructs recently arrived with a delivery of anima-rich spoils from the raid on Bastion. \n\nUse the maldracite crystal I've included in the parcel to extract enough anima for our ritual.", completion = "This should be sufficient.\n\nLet us prepare for the ritual.", objectives = "Drain anima from the Kyrian Spoils in the House of Rituals to fill the maldracite crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61742] = { id = 61742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting Guise", description = "The ritual to complete your disguise should be quite simple with the assistance of my oculus. Even a {class} like you should be able to manage it.\n\nWhen you are ready, simply hold the empowered crystal above Nelesis's corpse. My oculus will do the rest.", completion = "An impressive resemblance. You may just be able to pull this off.\n\nWell, what are you waiting for?", objectives = "Meet Balmedar in the Hall of Blades at the House of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61743] = { id = 61743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pupil Returns", description = "Now that you have your disguise--and I have assurance of your loyalty--it is time you reported to your new master.\n\nFind Kel'Thuzad within the Vault of Souls. Do whatever tasks he requires of you, but keep your eyes open for anything untoward.\n\nMy oculus will continue to accompany you so that I can provide guidance when the time is right.\n\nWe will uncover this new baron's true intentions.", completion = "Ah, you've returned. I take it the ritual went well?\n\nCome, we have much to accomplish.", objectives = "Meet Kel'Thuzad within the Vault of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61744] = { id = 61744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Baron's Plan", description = "You have done well in my service, Nelesis. When the time has come to take my rightful place, you will be well rewarded.\n\nUntil then, I will require your utmost devotion and secrecy.\n\nOur preparations are almost complete. Come, walk with me, and I will show you the splendor of our works.", progress = "Walk with me, acolyte.", completion = "There are but a few tasks remaining before we can complete our ritual.\n\nYou must begin immediately.", objectives = "Walk with Kel'Thuzad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61745] = { id = 61745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistress of Tomes", description = "The kyrian will no doubt make a worthy sacrifice for our ritual, but I am not entirely versed with the magics of his kind. I have requested that the Baroness Ninadar assemble a list of appropriate literature, so that I can ensure my ritual will have the desired effect.\n\nAs you know, the baroness enjoys exploiting her title, so expect to be faced with some manner of mundane tasks in exchange for her cooperation. \n\nReturn when you have procured the tomes, acolyte.", completion = "Kel'Thuzad always seems to have the most studious of pets, doesn't he?\n\nWhat is it the baron wishes of me, acolyte?", objectives = "Speak with Baroness Ninadar in the Grimoirium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61746] = { id = 61746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cantrip Collections", description = "One of the... more regrettable duties of the Mistress of Tomes is the collation and maintenance of our scroll library. Unfortunately, many of our acolytes are less than prompt when it comes to returning items they have borrowed, which requires me to seek them out and retrieve them myself.\n\nOf course, this is far too menial a task for a baroness, but that is why lackeys like you exist.\n\nGo, and retrieve my scrolls. Feel free to use whatever persuasive means you have at your disposal.", progress = "Have you found my scrolls?", completion = "Wonderful. Kel'Thuzad's pets are nothing if not reliable.\n\nWe are done here.", objectives = "Collect 6 Overdue Scrolls from Necrotic Acolytes in the Grimoirium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61747] = { id = 61747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errant Enchantments", description = "The House of Rituals is a place of constant study. Every day, new incantations and formulae are concocted to further the arts of necromancy. \n\nIt can be difficult to keep track of such innovation. To aid in cataloguing our progress, our sorcerers have applied the use of enchanted quills and parchment. Unfortunately, if not properly stored, these implements tend to run amok. \n\nOf course, they were not properly stored.  Find the implements and return them to where they belong.", progress = "Enchanted quills will not collect themselves, now will they?", completion = "Much better!\n\nI simply cannot abide a disorganized Grimoirium.", objectives = "Retrieve 4 Errant Quills and 6 Rampant Grimoires in the Grimoirium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61748] = { id = 61748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hall of Tomes", description = "Very well, you can have your list. The volumes you seek can be found in the Hall of Tomes.\n\nNow, run back to your master like a good little pet.", progress = "You have returned? Do you have my tomes?", completion = "Ah yes, these will do.\n\nIt will take some time to study these tomes. In the meantime, I have more need of you.", objectives = "Collect the required volumes from the Hall of Tomes and return them to Kel'Thuzad in the Vault of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61749] = { id = 61749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessary Ingredients", description = "As you are well aware, a ritual of this complexity requires several reagents. I have asked that Carver Jor'dan prepare what I'll need.\n\nSeek him out in the Reagentry, and provide whatever assistance he requests.", completion = "You are Kel'Thuzad's acolyte, are you not?", objectives = "Speak with Jor'dan the Powerful in the Reagentry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61750] = { id = 61750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Forest", description = "The baron requests a veilwing's heart, but procuring one is going to be something of a problem. \n\n<Jor'dan gestures to the disarray nearby.>\n\nAs you can plainly see, one of our sorcerers proved incapable of restraining the beast. I regret to inform you that our only specimen has escaped.\n\nIt cannot have gone far, though. If you follow its tracks you should be able to catch up with it and retrieve the heart yourself.\n\nI assure you the baron will not be able to perform his ritual without it.", progress = "Did you find the veilwing?", completion = "This specimen should work nicely for the baron's ritual.\n\nI will add it to his parcel.", objectives = "Collect a Veilwing's Heart from the Elusive Veilwing in the House of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61751] = { id = 61751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cage Free Spores", description = "I will need your assistance with the collection of one other reagent for your master. These spore clusters he requests--while normally a trivial matter--will require a bit of work.\n\nYou see, as the veilwing rampaged throughout the Reagentry, it toppled and broke several nearby cages hosting the blightrays from which we harvest the clusters.\n\nYou will have to collect them through more... conventional means. \n\nThe clusters are fragile, however, so try not to damage them while subduing the creatures.", progress = "Do you have the spore clusters?", completion = "This should do.\n\nI will assemble the reagents together to return to your master posthaste.", objectives = "Collect 6 Intact Spore Clusters from Escaped Blightrays in the Reagentry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61752] = { id = 61752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Reagent", description = "I have gathered most of the remaining reagents on your master's list. All that remains is the special shipment he requested from Oribos.\n\nThe brokers have yet to deliver the shipment. When it arrives, your master will have all he needs to complete his ritual.", progress = "Let us see what we have here.", completion = "Let me hold onto these for now.\n\nI will need you to get your hands on that shipment!", objectives = "Bring the Bundle of Reagents to Balmedar in the House of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61753] = { id = 61753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Schemes", description = "The brokers deal in objects most exotic and profound. If Kel'Thuzad requires reagents from them, his ritual must be outside the normal scope of the House of Rituals.\n\nThis mysterious reagent could be the key to unlocking Kel'Thuzad's plan. We must get a hold of this delivery from Oribos. \n\nI have taken the liberty of concocting an alchemical bomb. Use it to ambush the caravan and retrieve whatever they are transporting.", progress = "The caravan will arrive any moment now. Make haste!", completion = "Well done.\n\nNow we must work quickly, before we are discovered.", objectives = "Use the Alchemical Explosive to ambush the Broker caravan at the Scaplian Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61754] = { id = 61754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Crate Unturned", description = "That explosion will likely bring onlookers from the House of Rituals. We must act quickly.\n\nSearch through the debris for anything that looks out of the ordinary. It is likely that Kel'Thuzad's mystery reagent won't be hard to spot.", completion = "The runes on this blade... they are a hallmark of domination magic!\n\nThis is not good, {class}.", objectives = "Search the Broker's Crates for Kel'Thuzad's special reagent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61755] = { id = 61755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinding the Brokers", description = "We cannot allow Kel'Thuzad to discover who stopped his shipment. \n\nNone must be left to tell the tale of what transpired here.", completion = "The guards have been dealt with? Good.\n\nWe have more pressing matters, now.", objectives = "Kill 8 broker witnesses in the Scaplian Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61756] = { id = 61756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Designed to Fail", description = "The pieces are all coming together. The kyrian, the Paths of the First Ones, and runes of domination? \n\nKel'Thuzad is looking to breach the Maw!\n\nWe cannot allow this to happen! The Maw has been locked away from the Shadowlands for good reason. Opening that floodgate could be catastrophic!\n\nThe baron is too powerful to confront headlong, so we will stop his ritual instead. Return to him with his reagents. I have made some \"modifications\" that should provide a calamitous end to his scheme.", progress = "My acolyte returns. What have you brought me?", completion = "I see you managed to procure the reagents from Jor'dan, and... wait, what's this?\n\nI am impressed that you managed to procure the shipment from the brokers when my sorcerers could not!  \n\nYou are quite the resourceful one, acolyte!", objectives = "Bring the Bundle of \"Modified\" Reagents to Kel'Thuzad in the Vault of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61757] = { id = 61757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught in the Act", description = "Well then, since it was you who managed to procure the missing reagent, I find it only fair that you assist me with the final ritual! \n\nI can guarantee that this incantation will see you promoted to a full sorcerer of the house!\n\nThe preparations are already made. We can begin as soon as you are ready.", objectives = "Assist Kel'Thuzad in completing the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61758] = { id = 61758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improvised Implements", description = "There must be some way we can get ourselves out of these cells. \n\nI don't see anything I can use over here. Search your cell for anything that can facilitate our escape.", objectives = "Search your cell for something that can be used to escape.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61759] = { id = 61759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helpful Hand", description = "It takes but a simple act of necromancy to animate a hand. Unfortunately, since you will be in closest proximity, you must be the one to command it.\n\nWhen you are ready, I will reanimate the hand. Once you have control, use it to pull the lever at the end of the hall. \n\nCouldn't be simpler, right?", completion = "We have no time to lose!", objectives = "Navigate the Reanimated Hand to the end of the hall and activate the Corroded Lever.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61760] = { id = 61760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitor Unmasked", description = "We must waste no time in warning the margrave of Kel'Thuzad's treachery. His reckless toying with forbidden powers could bring ruin to the house and beyond!\n\nLet us put an end to this!", progress = "We must stop Kel'Thuzad before it's too late!", completion = "I didn't think we would make it out of that encounter intact.\n\nYou are truly a skilled {class}, {name}.", objectives = "Confront Kel'Thuzad in the Hall of Sorcery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61761] = { id = 61761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Better Part of Valor", description = "We now have no choice but to make a strategic retreat. Kel'Thuzad is far too fortified within the necropolis, and if Ninadar is his ally, then the House of Rituals is firmly in his grasp.\n\nIt will take nothing short of an army to save the margrave now.", completion = "The margrave has been captured? So Kel'Thuzad has seized control of the house!\n\nThis changes things.", objectives = "Return to the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61762] = { id = 61762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making a Smarter Dredger", description = "If he be hostin' fancy courts with you and Temel, this dredger's gotta be special...\n\nSmarter. Stronger. Quicker to apologize when they accidentally knock over the refreshments table and spill anima all over some poor duchess...\n\nI got an idea! Broker bloke at the Night Market was tryin' to sell me some important drinks. Kaja'Extreme or somethin'.\n\nSays it bigguns the brain, yeah? That's just what we need! \n\nTake these Scorchshrooms, that broker loves them, but note he rotates his costs each week.", progress = "You got the Kaja'Extreme?", completion = "Alright, {name}, let's make some muck!", objectives = "Purchase a bottle of Kaja'Extreme from Ta'tru at the Night Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61763] = { id = 61763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dredging up an Assistant", description = "Here we go, onto the dredging part.\n\nJust like we made that biggun here earlier!\n\nI mean we don't need the stone of binding or three other dredgers, but you'll still be throwing stuff into the muck!\n\nSo it's the same. \n\nYou head to the shore with this here Kaja-Infused Dredger Mix I whipped up for you.\n\nToss it into that muck pool and let's meet that new dredger butler of yours!", completion = "It worked! Of course I knew it would. Now what to name this guy... but first I am go'n to dismiss him so y'can test out the binding of the contract.", objectives = "Throw the Kaja-Infused Dredger Mix into the muck pool to create your dredger butler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61764] = { id = 61764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dredging up a Name", description = "Oi, why aren't you addressing me by my proper name? Wait, I don't remember my name, proper or other. Does this mean I have amnesias? Oh no, I don't have a name, please, help!", completion = "Oh yeah, that name totally fits my personality, or at least I think it does.", objectives = "Talk with your assistant and decide on a name for them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61765] = { id = 61765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Warding", description = "The towering citadel in the distance is protected by perilous walls, but its greatest dangers cannot be seen with mortal eyes.\n\nThe Mawsworn have placed invisible runes of warding throughout Perdition Hold. These traps have caught many intruders unaware.\n\nThe runes can be dispelled, but only if you can see them. I believe one of their soulcloaks should give you the sight you require.\n\nGood luck.", progress = "Are the wards gone? I am eager to resume surveillance of our enemy.", completion = "I trust you did not let your eyes wander while wearing the soulcloak? It can reveal some truly terrible things...", objectives = "Steal an Assassin's Soulcloak and dispel 4 Runes of Warding within Perdition Hold in The Maw.\n\nSuggested Players [3]", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61766] = { id = 61766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Homegrown Help", description = "Every good party herald needs an assistant. Which is why I have you!\n\nBut every good party herald's assistant... also needs an assistant.\n\nWhich is why I procured permission from the prince for you to create your own dredger butler. We can start him on security while we cozy up to the guests and procure the necessary reading materials to train him on the social protocols of the different realms. He'll be entertaining the whole court in no time. \n\nNo, don't thank me. You've earned this!", completion = "You ready to get your hands dirty?\n\nMakin' dredgers ain't pretty work.", objectives = "Meet Rendle in Dredgewood to make a dredger butler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61767] = { id = 61767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perilous Journey", description = "Mograine has rallied the House of the Chosen to strike at Margrave Gharmal and his House of Constructs. They grow in strength with each passing day--this may be our only chance.\n\nWe will join them on the field of battle. We will have justice for the fallen at my temple, as well as Mograine's own fallen kin.\n\nRendezvous at Spider's Watch within Maldraxxus' northern reaches. We will move from there.", completion = "Now we can join our new allies.", objectives = "Meet Xandria at Spider's Watch in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61768] = { id = 61768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Together", description = "We are to meet Baroness Draka aboard the Zerekriss above this position. Trust our allies' judgment in the battle ahead--true courage is knowing when to rely on the wisdom of others.\n\nThe plan is simple. Clear out our flanks to ensure Gharmal's forces do not interfere with our true goal, then assault the Margrave himself.\n\nIf we fail, we fail in the name of justice.", completion = "Welcome to Zerekriss, Maw Walker.", objectives = "Fly with Xandria into the necropolis Zerekriss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61769] = { id = 61769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight and Flight", description = "Alexandros and Emeni will lead the Chosen assault on the western gate. \n\nYou and Xandria will direct your forces at the eastern gate. Secure the area and eliminate any resistance. \n\nOnce both flanks are secured we can attack Gharmal directly.", completion = "This place is filled with horrors... horrors we will purge.", objectives = "Fly with Xandria to the House of Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61770] = { id = 61770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Butchers of Bastion", description = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these things?!\n\nNo! The butchers of Bastion made clear their hearts that day!\n\nThey deserve only the eternal darkness that awaits them. Ensure they see it!", progress = "Go bravely, {name}.", completion = "All this bloodshed will not bring them back... but it may spare others the same fate.", objectives = "Kill 10 House of Constructs forces in the Separation Chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61771] = { id = 61771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice from Above", description = "Our forces above cannot fully descend upon this area while the Margrave's crystals cover the sky in destructive blasts.\n\nThe Margrave's foul butchers work even now to extract the remaining anima from the kyrian they abducted in their assault on Bastion. We must advance at once.\n\nI shall imbue you with the flames of courage so that you may mark the crystals. Once marked, I will destroy them from afar.", completion = "You have done a great service here.", objectives = "Destroy 5 Maldracite Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61772] = { id = 61772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Developments", description = "<The torn design document appears to be written by the late Surgeon Stitchflesh.>\n\n...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential!\n\nNow, if subject number one-three-five succeeds in a proper wing transplant at last...\n\n<It continues on for some time. You should bring this to Artemede.>", completion = "Allow me to read this for a moment.", objectives = "Bring the Abhorrent Design to Artemede outside the Hall of Chains.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61773] = { id = 61773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descended", description = "Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple.\n\nAs I flew above their ranks I could hear their surgeons chanting its name above the din of combat--Woeblade. It is an affront to all the kyrian stand for, an atrocity beyond any other.\n\nMark it with the flames of courage when you engage, and we will help you destroy it.", completion = "May our victory bring them peace.", objectives = "Slay Woeblade the Atrocity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61774] = { id = 61774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Before Reading", description = "The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's abomination constructs.\n\nIt is also incomplete. There must be more of these among Stitchflesh's remaining followers.\n\nI saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls.\n\nWe must ensure they are never read again.", progress = "This foul work must be destroyed.", completion = "Well done. I will see that these are destroyed personally.", objectives = "Collect 6 Stitchflesh Designs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61775] = { id = 61775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Early End", description = "Within the Hall of Chains lie more abominations that are nearly complete. As we speak the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages.\n\nIf they are allowed to finish their work, the constructs we have destroyed so far will mean little in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost.\n\nThat must not come to pass. Destroy any abominations you come across.", progress = "May your blade strike true.", completion = "Every abomination denied is one less foe to contend with when we face Gharmal.", objectives = "Destroy 6 Inert Butchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61776] = { id = 61776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble on the Western Front", description = "Alexandros and our Maldraxxi allies need reinforcement at the western gate on the Margrave's opposite flank. They are barely holding on!\n\nOur forces will reinforce our position here and push forward towards Gharmal. We must make haste to Mograine--without both flanks we cannot hope to achieve victory.", completion = "I am glad Kynthia found you so quickly.", objectives = "Fly with Kynthia to report to Alexandros at the Stitchyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61777] = { id = 61777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging The Blade", description = "We can't advance with those juggernauts bombarding our position! I led a strike against the nearest, but conventional weapons do nothing against their imbued hides.\n\nThankfully, I have an idea.\n\nYour old runeblade can't deal with them as it stands, but if you could purge Gharmal's empowered masses and absorb their essence into the blade...", completion = "This is a long shot, but it just might work...", objectives = "Charge your runeblade by killing enemy constructs in the Stitchyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61778] = { id = 61778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Advantage", description = "Gharmal's rocs dominate the skies above, striking at our forces as we advance. The Zerekriss can't get into position until they are cleared out!\n\nI would take care of them myself, but I'm not much of a flier. Don't have the balance for it!\n\nTake my riding hook and latch onto a roc. Once you're riding, just start hitting it 'til the job is done.", progress = "Teach 'em a lesson!", completion = "I could hear their cries from here. Nice work!", objectives = "Grapple 6 Battlesewn Rocs out of the sky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61779] = { id = 61779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Intent", description = "My spies have identified several astral projectors that Margrave Gharmal uses to rally his troops in the Stitchyard.\n\nI do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor.\n\nSee to it that these projectors are destroyed. We believe them to be along the yard's perimeter.", progress = "A blow inflicted to the enemy's morale can be as effective as traditional combat.", completion = "Gharmal's influence runs deep in this place, but it will fade more quickly thanks to your efforts.", objectives = "Destroy the Southwestern, Northwestern, and Northeastern Astral Projectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61780] = { id = 61780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Chosen", description = "The Zerekriss is nearly in position. Now is the time to strike!\n\nWe must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts.\n\nThe Margrave will be unable to ignore their deaths. Once he leaves his blighted tower, we can finish him once and for all.", progress = "Every moment the juggernauts live our position is in jeopardy!", completion = "Such power! Gharmal will have no choice but to face us now.", objectives = "Destroy the Bilebloat Juggernauts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61781] = { id = 61781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End is Now", completion = "It is time.", objectives = "Meet with Xandria near the central chamber of the House of Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61782] = { id = 61782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pursuit of Justice", description = "Draka stands ready to unleash the power of the Zerekriss upon Gharmal. We need only buy her time to focus its weapon.\n\nWhat we do now, we do for all of us. Bastion and Maldraxxus have both lost many to these fiends.\n\nHe will not be defeated easily, but united our forces will finally bring him to justice!", completion = "Our fallen may finally rest in peace.", objectives = "Defeat Margrave Gharmal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61783] = { id = 61783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mega Bite", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61784] = { id = 61784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cliffs of Bastion", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61785] = { id = 61785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Expected Visitor", description = "One Alexandros Mograine of Maldraxxus is meeting with the Paragon of Courage in Archon's Rise. Xandria has requested you join them.\n\nThe two worked together recently to repel a nascent secondary assault on the Temple of Courage. Xandria seems to trust him well enough, so we have granted him access to the hold...for now.\n\nI suspect they will not stay here long. You should make haste.", completion = "Good. Now we can begin the mission.", objectives = "Speak with Xandria in Archon's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61786] = { id = 61786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Stonehead", objectives = "Your \"good bud\" Stonehead insists on fighting for the cause, {name}.\n\nI'm sure we can find a use for his skills. Nothing too complicated, of course.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61787] = { id = 61787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Micro Defense Force", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61788] = { id = 61788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Simone", objectives = "Your actions on behalf of Revendreth are garnering quite a lot of attention, {name}.\n\nSimone has offered to lend her expertise with the mirrors of the Ember Ward to the cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61789] = { id = 61789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Lost Sybille", objectives = "Lost Sybille comes highly recommended by Theotar.\n\nPlus, she dropped a bag of Stone Legion heads and two canisters of anima on our doorstep when she arrived. So I guess she's fighting for us already.\n\nLet's see what she can do with some allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61790] = { id = 61790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Vulca", objectives = "Anyone that survives in the Ember Ward as long as Vulca did is tough as stone.\n\nShe'll have an unexpected trick or two to help us take down the enemy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61791] = { id = 61791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thenia's Loyal Companions", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61792] = { id = 61792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Bogdan", objectives = "Your loyalty to Revendreth is unquestionable, {name}.\n\nBogdan has offered to take a leave of absence from Theotar's service, and will assist you however he can.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61813] = { id = 61813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valinor, the Light of Eons" }
quests[61814] = { id = 61814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nurgash Muckformed" }
quests[61815] = { id = 61815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oranomonos the Everbranching" }
quests[61816] = { id = 61816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortanis" }
quests[61839] = { id = 61839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nipping at the Undergrowth", description = "<The small gorger nips at your heels hungry and seeking your protection. Maybe it will like some of the plants here?>", progress = "Collect Endmire Vineroot for your small gorger.", completion = "<The gorger munches loudly on the vineroot and in between mouthfuls looks at you inquisitively.>", objectives = "Collect Endmire Vineroot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61840] = { id = 61840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vineroot on the Menu", description = "<Again the small gorger shows up and you can clearly see is looking for more Endmire Vineroot.>", progress = "Collect Endmire Vineroot for your small gorger.", completion = "<You barely get your hand back as the gorger snags the bundle. You can't help but notice he looks to be getting bigger. In between bites he spits out something.>", objectives = "Collect Endmire Vineroot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61841] = { id = 61841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Much to Goo On" }
quests[61842] = { id = 61842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vineroot Will Not Do", description = "<Clearly bigger, the gorger looks at a vineroot you point to and you can see the hint of menace in its eye at being offered the root again. It looks longingly at the devourer mites nearby.>", progress = "Collect Infused Endmire Fruit from the Devourer Mites in the Endmire or Banewood.", completion = "<When you drop the fruit at the feet of the gorger he devourers each one whole,  clearly it is enjoying them. Looking at you not eating it lets a couple fall for you.>", objectives = "Collect Infused Endmire Fruit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61844] = { id = 61844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Hungry Gorger", description = "<The gorger spawn bounded up to you, but was clearly looking at the devourer mites the entire time.>", progress = "Collect Infused Endmire Fruit from the Devourer Mites in the Endmire or Banewood.", completion = "<As you drop the fruit the gorger snaps some out of the air before they hit the ground. But you do see that the gorger has brought you a small item.>", objectives = "Collect Infused Endmire Fruit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61845] = { id = 61845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edict of Doom: Devourers", description = "The infusion of anima within Revendreth has led to a resurgence in devourer infestations. These eaters of the world must be slain.\n\nBy order of Prince Renathal and the rightful Court of Harvesters, this edict decrees the doom upon these aberrations.\n\nComplete this quota of destruction within Revendreth and receive a reward equal to your efforts.", completion = "Devourers. Filthy aberrations. We should have recognized their coming as the sign of the end times that they were.\n\nYou have our gratitude, Maw Walker.", objectives = "Destroy 20 Devourers in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61846] = { id = 61846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edict of Doom: Dredbats", description = "The recent suffusion of anima in the region has led to an increase in dredbats being animated far and above any intended volume.\n\nBy order of Prince Renathal and the true Court of Harvesters an edict of doom is declared on dredbats within Revendreth. \n\nAvoid those used for transport or assigned to specific duties, but slay any in the less tamed regions of the realm and a reward shall be proffered.", progress = "Maw Walker?", completion = "Ah, well done. Dredbats are useful entities when they serve their intended purpose. Left unchecked and untamed, however, they become competing predators for what few souls remain in our care.", objectives = "Destroy 25 Dredbats in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61847] = { id = 61847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overdue Purging", description = "There are many duties of a stoneborn that have been forsaken by the plans of Denathrius. \n\nOne such duty is the elimination of manifestations. The process venthyr use to extract anima from souls is not clean, and often leads to unresolved issues made manifest. \n\nThese entities are dangerous if left unchecked, and increase in number thanks to your revivication of anima to these droughted lands.\n\nWhile you patrol Revendreth, destroy any manifestations you encounter and I shall provide you recompense.", completion = "Your efforts are much appreciated. \n\nWhen this conflict is over, the Stone Legion should once again return to its noble purpose of protecting Revendreth, instead of satisfying the dark whims of Denathrius and his allies.", objectives = "Destroy 30 Manifestations in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61848] = { id = 61848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edict of Doom: Sinstone Golems", description = "By order of the true Court of Harvesters an edict of doom is issued for any Sinstone Golems that have coalesced into dangerous sizes within the realm. \n\nThese entities are the manifestation of unresolved sins of those souls who failed their redemption and were condemned to the Maw. With the recent suffusion of anima to the region they have grown dangerously strong.\n\nExpunge them from existence and recompense shall be provided.", completion = "You do the work the Stone Legion was once tasked to accomplish in better times. You have our gratitude.", objectives = "Destroy 4 Sinstone Golems in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61849] = { id = 61849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take the Bite Out of 'Em", description = "Right. So you got a quota of venthyr you need offed and I got a mean need for some payback.\n\nSee, you may not think it to look at me but 'em venthyr loooove to chew on me specifically. Not sure what dark habit followed them across the veil but I just was a squishy bag of indulgence for far too long.\n\nAs you go about offin' 'em venthyr for your normal... motivations... I'd ask you to bring me a bunch of fangs off 'em you off, as it were. \n\nI'll pay for payback!", progress = "I'm gettin' quite a collection goin'.", completion = "Much obliged. This will go a long way to servin' \"restitutions\" as 'em fang heads would say.", objectives = "Collect 40 Venthyr Fangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61851] = { id = 61851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shades of Muck", description = "Yeah, this here muck pool's got everythin' we need to make your dredger butler.\n\nWe'll make this one special just for you. Made to specifications, as the fangs say.\n\nFirst up, you gotta choose its color. Us dredgers comes in all kind of different shades of muck.\n\nTake a peek at some me fellow dredgers and let me know what color we should dredge up for your butler.\n\nWe can recolor a dredger after-the-fact, but it ain't pleasant.\n\n<Rendle shudders at the thought.>", progress = "What color you thinkin' of?", completion = "I'll get the pigment all ready for you, but we're gonna need a little something extra for this dredger mucking.", objectives = "Look at nearby dredgers to see color options, and then tell Rendle which color you want.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61852] = { id = 61852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Guardian Kota", objectives = "Hello again, {name}. It is good to see you taking such an active interest in the affairs of Ardenweald.\n\nThe honorable Guardian Kota has agreed to work with us, as part of her duties to protect the grove of Tirna Vaal.\n\nTogether, you will ensure the forest's continued security.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61853] = { id = 61853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Te'zan", objectives = "The forest is ever in need, {name}.\n\nTe'zan is as spirited as ever, and perhaps a healthy dose of responsibility will lend him some direction and meaning to his afterlife.\n\nWhere should we send him first?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61854] = { id = 61854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Master Sha'lor", objectives = "The forest blesses us today, {name}.\n\nMaster Sha'lor says he has sufficiently recovered from his ordeal with the gorm, and would like to be of assistance however he can. He seems especially eager to learn new things.\n\nI guess a little taste of adventure goes a long way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61855] = { id = 61855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Qadarin", objectives = "Good to see you again, {name}.\n\nYour continued dedication to the well-being of Ardenweald has not gone unnoticed.\n\nQadarin has expressed interest in taking a more active role. Let's put his skills to use, shall we?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61856] = { id = 61856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Watcher Vesperbloom", objectives = "I have a particularly special boon for you, o' champion of Ardenweald. Are you ready?\n\nThe individual joining our Hunt today is... me!\n\n<Vesperbloom rubs her hands together, grinning.>\n\nIt will be nice to get in some field work!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61857] = { id = 61857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Groonoomcrooek", objectives = "{name}, your devotion to Ardenweald, and to the Queen, is unquestionable.\n\nSomething you've done seems to have satisfied Groonoomcrooek. I'm not sure exactly what it was, though.\n\nIt took them a while just to tell me they would be joining us here.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61859] = { id = 61859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Nemea", objectives = "It is good to see you again, {name}.\n\nA friend of yours has kindly offered to assist in our endeavors here: Nemea, the larion master. She will be a powerful ally.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61860] = { id = 61860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Pelodis", objectives = "It is good to see you again, {name}.\n\nA friend of yours has kindly offered to assist in our endeavors here: Pelodis, the phalynx master. He will be a powerful ally.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61861] = { id = 61861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Sika", objectives = "It seems we have another recruit, {name}.\n\nSika has asked to aid us here whenever she is not tending to her duties at the Eternal Forge.\n\nDo not underestimate her worth as an ally!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61862] = { id = 61862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Clora", objectives = "{name}, I would ask for a moment of your time.\n\nOne of the recently ascended, Clora, feels that her fierce combat skills would be best put to use tackling the matters laid out before us. I am inclined to agree.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61863] = { id = 61863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Apolon", objectives = "Hello there, my mortal friend! I have good news for you today.\n\nApolon has told me with great certainty that the path he follows is intertwined with yours.\n\nThough he has duties to the Path of Ascension, his courage will be of great aid to us here as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61864] = { id = 61864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Bron", objectives = "Mikanikos has made a sensible suggestion, {name}.\n\nWhen Bron is not directly assisting you in the field, he could be of service elsewhere throughout the Shadowlands.\n\nI am sure Bron will not mind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61865] = { id = 61865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Disciple Kosmas", objectives = "Your dedication to Bastion is inspiring, {name}.\n\nWith the anima you have returned to us, Disciple Kosmas feels he can be away from the Temple of Purity for a time.\n\nHe has offered to join us here at the Hold, and contribute to the greater needs of the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61866] = { id = 61866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mighty Minions of Maldraxxus", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61867] = { id = 61867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extra Pieces", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61868] = { id = 61868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncomfortably Undercover", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61869] = { id = 61869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search the Place", description = "Zerekriss is ours... along with everything it contains.\n\nThe Primus was personally involved in the design of this necropolis. It was truly a sight to witness his hands shape the form of this vessel.\n\nIt would be wise to search the room. Perhaps he kept some tools here that might be of use to us.", progress = "What did you find?", completion = "These belonged to the Primus!", objectives = "Check the Foreman's Chest for anything valuable.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61870] = { id = 61870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Failed Experiment", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61871] = { id = 61871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Current Matters", description = "Ye've done good here, champion. MOTHER and I will be figurin' out what te do next.\n\nYe best get back te matters at hand, and do what ye can te empower that necklace o' yours.\n\nI've got ways te reach ye once MOTHER and I have fixed things up here.", completion = "You're back. I suppose there's something around here for you to do.", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61872] = { id = 61872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Current Matters", description = "Ye've done good here, champion. MOTHER and I will be figurin' out what te do next.\n\nYe best get back te matters at hand, and do what ye can te empower that necklace o' yours.\n\nI've got ways te reach ye once MOTHER and I have fixed things up here.", completion = "{name}, it is good to see you again. There's much to do around here.", objectives = "Return to Halford Wyrmbane on the Wind's Redemption in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61874] = { id = 61874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands: A Chilling Summons", description = "The time has come, {class}.\n\nHighlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Orgrimmar, and I will take you to him.\n\nI would not keep him waiting.", completion = "It is good that you have arrived.\n\nWe need heroes like you in this dire hour.", objectives = "Meet Darion Mograine outside Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61875] = { id = 61875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing the Dew", description = "The Thistledrop is magnificent creature. The roots go deep into the earth where they drink of waters most ancient. With these waters they collect the very essence of the land into a drop of dew that enables our artisans to craft powerful armaments.\n\nHelp us gather the dew and you will be well rewarded.\n\nHurry, before it evaporates!", progress = "The dew evaporates quickly, hurry now!", completion = "This dew will help our craftmasters a great deal!\n\nThank you, little one.", objectives = "Collect 30 Thistledrop Dew in Ardenweald's Forests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61876] = { id = 61876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Heart", description = "Mograine and I spoke at length when he visited Bastion. He suggested that should we manage to kill Gharmal, his heart could be used to empower the Crest of Ascension.\n\nThe Margrave bears the power to shape form in ways few beings can. Though his results are grim, if we could harness that power our Ascended would be stronger than ever before.\n\nIt is not our way, but our way is changing, I think. Perhaps this is a step on our new path.", progress = "It must be done.", completion = "I am relieved that I am not the one to carry that thing back to Bastion.", objectives = "Collect the Fleshshaper's Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61877] = { id = 61877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Hold", description = "Let us ferry the heart to Elysian Hold swiftly.\n\nThere are many in the Shadowlands who would strike at us to take its power for their own. Keep your eyes open, Maw Walker.\n\nWe return to our kin victorious this day.", completion = "I am glad to be among our own once more. Maldraxxus is not to my tastes.", objectives = "Meet Xandria at the Crest of Ascension in Elysian Hold in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61878] = { id = 61878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crest of Greatness", description = "Once you are ready, all you must do is place the heart within the sphere here on the Crest of Ascension.\n\nMikanikos's handiwork will ensure that its energy is channeled properly to aid in our ascension rituals, and its power should help protect the Crest against any further attack.\n\nMay the House of Constructs never set foot in our realm again.", progress = "<This looks to be the orb Xandria directed you to place the heart in.>", completion = "<The Fleshshaper's Heart fits readily into the glowing sphere. As it enters, you hear faint clicking sounds within the Crest, as if it were designed to accept such power readily.\n\nThus begins a new era for the kyrian.>", objectives = "Place the Fleshshaper's Heart in the Crest of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
